    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost = -1
    for i in range(n-1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost = i + 1
            break
    return topmost

