def cantor_numbering(N: int) -> str:
    numerator = 1
    denominator = 1
    direction = 1
    current_position = 1

    while current_position < N:
        if direction == 1:
            if numerator + 1 + denominator > N:
                numerator = N - sum(range(1, denominator))
            else:
                numerator += 1
                denominator += 1
        else:
            if numerator + 1 + denominator > N:
                denominator = N - sum(range(1, numerator))
            else:
                numerator += 1
                denominator += 1
        direction *= -1
        current_position += 1

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    # Split the number string based on K multiplication signs
    parts = []
    temp = ""
    mul_count = 0
    for char in num_str:
        if char == 'x':
            mul_count += 1
            if mul_count == K + 1:
                parts.append(temp)
                temp = ""
            else:
                parts.append(temp)
                temp = ""
        else:
            temp += char
    parts.append(temp)

    # Convert parts to integers and calculate the product
    product = 1
    for part in parts:
        product *= int(part)

    return product

