def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps > 10:
            return "NO ANSWER!"

        for old, new in rules:
            index = current.find(old)
            if index == -1:
                continue

            new_string = current[:index] + new + current[index + len(old):]
            if new_string == B:
                return steps + 1

            if new_string not in visited:
                visited.add(new_string)
                queue.append((new_string, steps + 1))

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque

    def apply_rules(number):
        str_num = str(number)
        for x, y in rules:
            str_num = str_num.replace(str(x), str(y))
        return int(str_num)

    queue = deque([n])
    visited = set([n])

    while queue:
        current = queue.popleft()
        for i in range(10):
            transformed = apply_rules(current + i * 10**len(str(current)))
            if transformed not in visited:
                visited.add(transformed)
                queue.append(transformed)

    return len(visited)

