def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    decrypted_text = []

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            shift = ord(key[i % key_length].lower()) - ord('a')
            if char.islower():
                decrypted_text.append(chr((ord(char) - ord('a') - shift) % 26 + ord('a')))
            else:
                decrypted_text.append(chr((ord(char) - ord('A') - shift) % 26 + ord('A')))
        else:
            decrypted_text.append(char)

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    original_b = b
    if b == 1:
        return 0
    x0, x1, y0, y1 = 0, 1, 1, 0
    while a > 1:
        q, a, b = b // a, b % a, a
        x0, x1 = x1 - q * x0, x0
        y0, y1 = y1 - q * y0, y0
    if x1 < 0:
        x1 += original_b
    return x1 if b == 1 else None

